Cool idea. Let’s build the **first playable piece**: a cat moves left and right, and fish fall down. You can play it right away.

Before you change anything: what do you think should happen when the cat catches a fish?

Copy this into a file called `cat-fish-game.html`, then open it in a browser:

```html
<!DOCTYPE html>
<html>
<head>
  <title>Cat Fish Catch</title>
  <style>
    body {
      margin: 0;
      background: skyblue;
      overflow: hidden;
      font-family: Arial, sans-serif;
    }

    #score {
      position: absolute;
      top: 10px;
      left: 10px;
      font-size: 28px;
      font-weight: bold;
    }

    #cat {
      position: absolute;
      bottom: 20px;
      left: 200px;
      font-size: 60px;
    }

    #fish {
      position: absolute;
      top: 0px;
      left: 100px;
      font-size: 40px;
    }
  </style>
</head>
<body>
  <div id="score">Score: 0</div>
  <div id="cat">🐱</div>
  <div id="fish">🐟</div>

  <script>
    const cat = document.getElementById("cat");
    const fish = document.getElementById("fish");
    const scoreText = document.getElementById("score");

    let catX = 200;
    let fishX = 100;
    let fishY = 0;
    let score = 0;

    document.addEventListener("keydown", function(event) {
      if (event.key === "ArrowLeft") {
        catX = catX - 20;
      }

      if (event.key === "ArrowRight") {
        catX = catX + 20;
      }

      cat.style.left = catX + "px";
    });

    function dropFish() {
      fishY = fishY + 5;
      fish.style.top = fishY + "px";
      fish.style.left = fishX + "px";

      let catLeft = catX;
      let catRight = catX + 60;
      let fishLeft = fishX;
      let fishRight = fishX + 40;

      let fishNearCat = fishY > window.innerHeight - 120;
      let fishTouchesCat = fishRight > catLeft && fishLeft < catRight;

      if (fishNearCat && fishTouchesCat) {
        score = score + 1;
        scoreText.textContent = "Score: " + score;
        resetFish();
      }

      if (fishY > window.innerHeight) {
        resetFish();
      }
    }

    function resetFish() {
      fishY = 0;
      fishX = Math.random() * (window.innerWidth - 50);
    }

    setInterval(dropFish, 30);
  </script>
</body>
</html>
```

Use the **left and right arrow keys** to move the cat.

A good next step: try changing this line:

```js
fishY = fishY + 5;
```

Change `5` to `10`. What happens to the fish?

When you finish testing it, show it to a grown-up or someone nearby. Also take a little break after playing for a bit.

