    top: 0px;
    left: 300px;
    font-size: 40px;
  }
</style>

<script>
  const cat = document.getElementById("cat");
  const fish = document.getElementById("fish");
  const bomb = document.getElementById("bomb");
  const scoreText = document.getElementById("score");
  const heartsText = document.getElementById("hearts");
  const message = document.getElementById("message");
  const restartButton = document.getElementById("restartButton");

  let catX = 200;

  let fishX = 100;
  let fishY = 0;

  let bombX = 300;
  let bombY = -300;

  let score = 0;
  let hearts = 3;
  let gameOver = false;

  let catSpeed = 40;
  let fishSpeed = 5;
  let bombSpeed = 4;

  function beepSound(frequency, length) {
    const audio = new AudioContext();
    const sound = audio.createOscillator();
    const volume = audio.createGain();

    sound.connect(volume);
    volume.connect(audio.destination);

    sound.frequency.value = frequency;
    volume.gain.value = 0.15;

    sound.start();
    sound.stop(audio.currentTime + length);
  }

  function yumSound() {
    beepSound(500, 0.12);
  }

  function splatSound() {
    beepSound(100, 0.2);
  }

  function boomSound() {
    beepSound(60, 0.35);
  }

  document.addEventListener("keydown", function(event) {
    if (gameOver) {
      return;
    }

    if (event.key === "ArrowLeft") {
      catX = catX - catSpeed;
    }

    if (event.key === "ArrowRight") {
      catX = catX + catSpeed;
    }

    if (catX < 0) {
      catX = 0;
    }

    if (catX > window.innerWidth - 70) {
      catX = window.innerWidth - 70;
    }

    cat.style.left = catX + "px";
  });

  restartButton.addEventListener("click", function() {
    restartGame();
  });

  function showHearts() {
    heartsText.textContent = "❤️".repeat(hearts);
  }

  function catTouchesThing(thingX, thingY, thingWidth) {
    let catLeft = catX;
    let catRight = catX + 60;

    let thingLeft = thingX;
    let thingRight = thingX + thingWidth;

    let thingNearCat = thingY > window.innerHeight - 120;
    let thingTouchesCat = thingRight > catLeft && thingLeft < catRight;

    return thingNearCat && thingTouchesCat;
  }

  function loseHeart() {
    hearts = hearts - 1;
    showHearts();

    if (hearts <= 0) {
      endGame();
    }
  }

  function dropFish() {
    fishY = fishY + fishSpeed;
    fish.style.top = fishY + "px";
    fish.style.left = fishX + "px";

    if (catTouchesThing(fishX, fishY, 40)) {
      score = score + 1;
      scoreText.textContent = "Score: " + score;
      yumSound();
      resetFish();
    }

    if (fishY > window.innerHeight - 40) {
      fish.textContent = "💥";
      message.textContent = "SPLAT!";
      splatSound();
      loseHeart();

      setTimeout(function() {
        message.textContent = "";
        fish.textContent = "🐟";

        if (!gameOver) {
          resetFish();
        }
      }, 500);
    }
  }

  function dropBomb() {
    bombY = bombY + bombSpeed;
    bomb.style.top = bombY + "px";
    bomb.style.left = bombX + "px";

    if (catTouchesThing(bombX, bombY, 40)) {
      message.textContent = "BOOM!";
      bomb.textContent = "💥";
      boomSound();
      loseHeart();

      setTimeout(function() {
        message.textContent = "";
        bomb.textContent = "🔴";

        if (!gameOver) {
          resetBomb();
        }
      }, 500);
    }

    if (bombY > window.innerHeight) {
      resetBomb();
    }
  }

  function resetFish() {
    fishY = 0;
    fishX = Math.random() * (window.innerWidth - 50);
  }

  function resetBomb() {
    bombY = -200;
    bombX = Math.random() * (window.innerWidth - 50);
  }

  function endGame() {
    gameOver = true;
    message.textContent = "Game Over!";
    fish.style.display = "none";
    bomb.style.display = "none";
    restartButton.style.display = "block";
  }

  function restartGame() {
    catX = 200;

    fishX = 100;
    fishY = 0;

    bombX = 300;
    bombY = -300;

    score = 0;
    hearts = 3;
    gameOver = false;

    scoreText.textContent = "Score: 0";
    showHearts();
    message.textContent = "";
    restartButton.style.display = "none";

    cat.style.left = catX + "px";

    fish.textContent = "🐟";
    fish.style.display = "block";

    bomb.textContent = "🔴";
    bomb.style.display = "block";

    resetFish();
    resetBomb();
  }

  function gameLoop() {
    if (gameOver) {
      return;
    }

    dropFish();
    dropBomb();
  }

  showHearts();
  setInterval(gameLoop, 30);
</script>
```

The new important part is this:

```js
function dropBomb() {
```

That function means: “move the bomb down, check if the cat touches it, and reset it.”

